# b56-compute (wave 16).  Hook certificate N = span{e_x (x) e_T : x in T} in V (x) Lambda^k V, k EVEN (f = k+1 odd),
# demand f(K) certified by mod-p ranks, with one more symmetry than b56.py: an elementary abelian group G of bit
# permutations generated by disjoint bit transpositions (they commute with K = dir(e1)...dir(em), keep N, fix the
# X-character alpha = 0 and the class of every Walsh tuple).  For odd f all X-characters give the same part
# (Z_s maps E_alpha -> E_{alpha+s}), so f(K) = n * f(K | E_0); E_0 splits further into the 2^r characters chi of G.
# Columns: (0, T) with 0 in T (exact shift-orbit reps: shifts act freely), reduced to G-orbit reps; the chi-column is
#   sum_g chi(g) sgn(g,T) e_{(0, gT)} projected to E_0; distinct (G x shift)-orbits have disjoint supports, so
#   rank C_chi = number of nonzero chi-columns EXACTLY [proved].
# Rows: Walsh tuples (s, U) with s = xor(U) (alpha = 0), one per G-orbit (rows in a G-orbit are proportional on
#   chi-columns).  f(K | E_0, chi) = rank C_chi[class c1] + rank C_chi[class c2] - rank C_chi.
# Usage: python3 -I hookG.py M K 01,23,45 [--threads T]
import sys, os, itertools, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import b56
import numpy as np
from math import comb

def bitswap(x, i, j):
    bi, bj = (x >> i) & 1, (x >> j) & 1
    if bi != bj: x ^= (1 << i) | (1 << j)
    return x

def main():
    args = sys.argv[1:]
    if '--threads' in args:
        b56.NTHREADS = int(args[args.index('--threads') + 1])
    m, k = int(args[0]), int(args[1]); gens = [tuple(int(c) for c in g) for g in args[2].split(',')]
    n = 1 << m; f = k + 1; assert k % 2 == 0
    t0 = time.time()
    r = len(gens)
    G = list(itertools.product((0, 1), repeat=r))
    perms = []
    for gv in G:
        pm = list(range(n))
        for use, (i, j) in zip(gv, gens):
            if use: pm = [bitswap(x, i, j) for x in pm]
        perms.append(np.array(pm, dtype=np.int64))
    # all k-sets as sorted arrays
    sets = np.array(list(itertools.combinations(range(n), k)), dtype=np.int64)
    w = 1 << np.arange(n, dtype=np.uint64)
    def mask(arr): return np.bitwise_or.reduce(w[arr], axis=1)
    # ---- columns: T with 0 in T, G-orbit reps ----
    colT = sets[sets[:, 0] == 0]
    cm = mask(colT)
    canon = cm.copy()
    for pm in perms[1:]:
        canon = np.minimum(canon, mask(pm[colT]))
    _, ci = np.unique(canon, return_index=True)
    colT = colT[np.sort(ci)]
    # ---- rows: U arbitrary, G-orbit reps ----
    um = mask(sets)
    canon = um.copy()
    for pm in perms[1:]:
        canon = np.minimum(canon, mask(pm[sets]))
    _, ri = np.unique(canon, return_index=True)
    rowU = sets[np.sort(ri)]
    # paid element g: K (default), R = dir(e1) ('--lab b0'), dir(e1)dir(e2) ('--lab b01'); eigenvalue on h_s = i^lab(s)
    labmode = args[args.index('--lab') + 1] if '--lab' in args else 'K'
    labmask = n - 1 if labmode == 'K' else sum(1 << int(c) for c in labmode[1:])   # 'b012' = dir(e1)dir(e2)dir(e3)
    for (i, j) in gens:      # every bit swap must commute with g: keep the set of label bits
        assert ((labmask >> i) & 1) == ((labmask >> j) & 1), "bit swap does not commute with g"

    pc = np.array([bin(x & labmask).count('1') for x in range(n)])
    s_of = np.bitwise_xor.reduce(rowU, axis=1)
    rcls = (pc[s_of] + pc[rowU].sum(axis=1)) % 4
    rowlist = np.concatenate([s_of[:, None], rowU], axis=1).astype(np.uint8)
    print(f"m={m} k={k} G=<{args[2]}> |G|={len(G)}: dim N {k*comb(n,k)}, E_0 columns {k*comb(n,k)//n} -> G-reps {len(colT)}, "
          f"rows {len(sets)} -> G-reps {len(rowU)}, classes {sorted(set(rcls.tolist()))}  ({time.time()-t0:.1f}s)", flush=True)
    # transformed columns g T (sorted) and signs
    gcols, gsgn = [], []
    for pm in perms:
        img = pm[colT]
        order = np.argsort(img, axis=1, kind='stable')
        srt = np.take_along_axis(img, order, axis=1)
        inv = np.zeros(len(img), dtype=np.int64)
        for a in range(k):
            for b in range(a + 1, k):
                inv += (img[:, a] > img[:, b])
        gsgn.append(np.where(inv % 2, -1.0, 1.0))
        gcols.append(np.concatenate([np.zeros((len(img), 1), dtype=np.int64), srt], axis=1).astype(np.uint8))
    total = 0; nzsum = 0
    classes = sorted(set(rcls.tolist()))
    only = int(args[args.index('--chi') + 1]) if '--chi' in args else None    # checkpointing: one character per run
    for ci, ch in enumerate(G):
        if only is not None and ci != only: continue
        chiv = [(-1) ** sum(a * b for a, b in zip(ch, gv)) for gv in G]
        colnz = np.zeros(len(colT), bool)
        rks = {}
        for c in classes:
            rl = rowlist[rcls == c]
            CH = max(1, int(3e6 // max(1, len(colT))))
            def gen(rl=rl, CH=CH):
                for st in range(0, len(rl), CH):
                    acc = None
                    for gi in range(len(G)):
                        F = b56.fill([1, k], rl[st:st + CH], gcols[gi]) * (chiv[gi] * gsgn[gi])[None, :]
                        acc = F if acc is None else acc + F
                    colnz[:] |= (acc != 0).any(axis=0)
                    yield acc
            rk, Y = b56.compress_rank(gen, len(colT), len(rl), seed=7 + c)
            del Y
            rks[c] = rk
        nz = int(colnz.sum())
        part = sum(rks.values()) - nz if len(classes) == 2 else 0
        total += part; nzsum += nz
        print(f"  chi={ch}: nonzero cols {nz}, ranks {rks}, part {part}  ({time.time()-t0:.1f}s)", flush=True)
    dimN = k * comb(n, k)
    if only is not None:
        print(f"PARTIAL hookG m={m} k={k} chi#{only}: part {total}, nonzero cols {nzsum}  (sum parts x n over all chi; "
              f"rank check: n * sum nonzero cols must equal {dimN})", flush=True)
        return
    ok = n * nzsum == dimN
    val = n * total
    delta = k * comb(n, k) - comb(n, k - 1)
    print(f"RESULT hookG m={m} k={k} g={labmode}: dim N {dimN}, rank check {n*nzsum} {'EXACT' if ok else 'MISMATCH'}, f(K) >= {val}"
          f"{' (certified)' if ok else ' (NOT certified)'}; delta upper bound {delta}  ({time.time()-t0:.1f}s)", flush=True)

if __name__ == '__main__':
    main()
